{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment Plans — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Intensive, context-aware care plans to restore balance and clarity in everyday life.">
  <style>
    :root{
      --bg:#fbf6f0;
      --card:#fff7f0;
      --ink:#2b2a28;
      --accent:#9a5a2a;
      --muted:#7a6a60;
      --shadow: 0 6px 18px rgba(41,28,18,0.08);
      --pattern: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200"><defs><pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse"><rect width="40" height="40" fill="%23fbf6f0"/><path d="M0 20 Q10 10 20 20 T40 20" stroke="%239a5a2a" stroke-opacity="0.06" stroke-width="2" fill="none"/><circle cx="6" cy="6" r="1.6" fill="%239a5a2a" opacity="0.06"/></pattern></defs><rect width="200" height="200" fill="url(%23p)"/></svg>');
    }
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial; background:var(--bg) var(--pattern); color:var(--ink); line-height:1.45}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#c0743d);display:flex;align-items:center;justify-content:center;color:white;font-weight:700;box-shadow:var(--shadow)}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:980px;margin:28px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:26px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.9));box-shadow:var(--shadow)}
    .eyebrow{color:var(--accent);font-weight:700}
    h1{margin:6px 0 0;font-size:clamp(20px,3.6vw,32px)}
    .lede{color:var(--muted)}
    .plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px;margin-top:18px}
    .plan{background:var(--card);padding:18px;border-radius:10px;box-shadow:var(--shadow);border:1px solid rgba(0,0,0,0.02)}
    .plan h3{margin:0 0 8px}
    .price{font-size:20px;color:var(--accent);font-weight:700}
    .features{margin:12px 0;color:var(--muted);font-size:14px}
    .cta{display:inline-block;margin-top:8px;padding:10px 14px;border-radius:8px;background:var(--accent);color:white;text-decoration:none;font-weight:700}
    .small{font-size:13px;color:var(--muted)}
    footer{margin-top:26px;padding:18px;border-radius:10px;background:transparent;color:var(--muted);text-align:center}

    /* modal */
    .modal-backdrop{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(12,8,6,0.45);z-index:60}
    .modal{width:min(720px,94%);background:white;border-radius:12px;padding:20px;box-shadow:0 20px 60px rgba(10,6,4,0.6)}
    .modal header{display:flex;justify-content:space-between;align-items:center}
    .modal h2{margin:0}
    .close-btn{background:transparent;border:0;font-size:18px}
    .exercise-stage{margin-top:14px}
    .breath-circle{width:140px;height:140px;border-radius:999px;background:radial-gradient(circle at 30% 30%,rgba(154,90,42,0.12),rgba(154,90,42,0.06));margin:18px auto;display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    .controls{display:flex;gap:8px;justify-content:center;margin-top:10px}
    button.kv{padding:8px 12px;border-radius:8px;border:1px solid #e8d5c8;background:#fff;cursor:pointer}

    /* reveal animation */
    .reveal{opacity:0;transform:translateY(16px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}

    @media (prefers-reduced-motion:reduce){
      .reveal{transition:none;transform:none;opacity:1}
      .breath-circle{transition:none}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Begin</a>
      <a href="services.html">Offerings</a>
      <a href="approach.html">Philosophy</a>
      <a href="pricing.html" style="color:var(--ink)">Invest</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" id="intro">
      <div class="eyebrow">Investment paths for concentrated change</div>
      <h1>Intensive cycles and focused packages</h1>
      <p class="lede">We design short, deep courses of care—rooted in context, tailored to routines—so you can shift patterns with intention and practical supports. Choose a path that matches your current needs and time.</p>

      <div class="plans" aria-label="Programs">
        <article class="plan" id="plan-ignite">
          <h3>Ignite — 6-week intensive</h3>
          <div class="price">$1,900</div>
          <div class="features">Weekly 60-min sessions, 24/7 messaging, tailored tools for sleep & energy, onboarding lab review</div>
          <a class="cta" href="book.html?plan=ignite">Reserve Ignite</a>
          <div class="small">Flexible financing available</div>
        </article>

        <article class="plan" id="plan-restore">
          <h3>Restore — 12-week focus</h3>
          <div class="price">$3,600</div>
          <div class="features">Bi-weekly visits, structured habit-building track, group check-ins, custom meal & movement guidance</div>
          <a class="cta" href="book.html?plan=restore">Join Restore</a>
          <div class="small">Most popular for steady change</div>
        </article>

        <article class="plan" id="plan-standby">
          <h3>Standby — ongoing coaching</h3>
          <div class="price">$180 / month*</div>
          <div class="features">Monthly check-ins, priority messaging, brief plan adjustments, drop-in intensives</div>
          <a class="cta" href="book.html?plan=standby">Start Standby</a>
          <div class="small">*Minimum 3 months</div>
        </article>
      </div>

      <div style="margin-top:14px;display:flex;gap:10px;align-items:center">
        <button class="kv" id="try-exercise">Try a short exercise</button>
        <div class="small">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </section>

    <section class="reveal" id="notes" style="margin-top:18px;padding:16px;border-radius:10px;background:rgba(255,255,255,0.6)">
      <h3>What these packages include</h3>
      <ul style="color:var(--muted)">
        <li>Personalized plan maps and simple daily practices that fit your life rhythm</li>
        <li>Clear metrics to measure progress and timely adjustments</li>
        <li>Education-first approach—no promises, only tools to try</li>
      </ul>
    </section>

    <footer>
      <div class="small">Ready to commit to a focused track? <a href="book.html">Book a consult</a> or use the primary action: <a href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>.</div>
    </footer>
  </main>

  <div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <header>
        <h2 id="modal-title">Guided moment</h2>
        <button class="close-btn" id="close-modal" aria-label="Close">✕</button>
      </header>
      <div id="modal-body">
        <p class="small">Choose a short practice below to re-center. Each runs locally in your browser.</p>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">
          <button class="kv" data-mode="breathing">Breathing</button>
          <button class="kv" data-mode="journaling">Journaling</button>
          <button class="kv" data-mode="intention">Set intention</button>
        </div>

        <div class="exercise-stage" id="exercise" aria-live="polite"></div>
      </div>
    </div>
  </div>

  <script>
    /* Scroll reveal with prefers-reduced-motion */
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealables = document.querySelectorAll('.reveal');
      if(prefersReduce){
        revealables.forEach(el => el.classList.add('visible'));
        return;
      }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target); } });
      },{threshold:0.12});
      revealables.forEach(el=>obs.observe(el));
    })();

    /* Guided exercise modal */
    (function(){
      const modal = document.getElementById('modal');
      const modalBody = document.getElementById('exercise');
      const openBtn = document.getElementById('try-exercise');
      const closeBtn = document.getElementById('close-modal');
      openBtn.addEventListener('click',()=>{ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; });
      closeBtn.addEventListener('click',closeModal);
      modal.addEventListener('click',(e)=>{ if(e.target===modal) closeModal(); });
      function closeModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); document.body.style.overflow=''; modalBody.innerHTML=''; }

      // mode buttons
      modal.querySelectorAll('button[data-mode]').forEach(btn=>btn.addEventListener('click',()=>startMode(btn.getAttribute('data-mode'))));

      let breathTimer=null;
      function startMode(mode){ modalBody.innerHTML=''; if(breathTimer){ clearInterval(breathTimer); breathTimer=null; }
        if(mode==='breathing') return startBreathing();
        if(mode==='journaling') return startJournaling();
        if(mode==='intention') return startIntention();
      }

      function startBreathing(){
        modalBody.innerHTML = '<div style="text-align:center"><div class="breath-circle" id="circle">Inhale</div><div class="small" id="phase">3s</div><div class="controls"><button class="kv" id="stop">Stop</button></div></div>';
        const circle = document.getElementById('circle');
        const phase = document.getElementById('phase');
        const stop = document.getElementById('stop');
        let step=0; // 0 inhale,1 hold,2 exhale
        const pattern = [4,4,6]; // seconds inhale, hold, exhale
        const labels=['Inhale','Hold','Exhale'];
        function tick(){
          let secs = pattern[step];
          phase.textContent = secs + 's';
          circle.textContent = labels[step];
          circle.style.transform = (step===0) ? 'scale(1.15)' : (step===2) ? 'scale(0.86)' : 'scale(1)';
          circle.style.transition = 'transform '+(secs)+'s ease-in-out';
          let c=secs;
          breathTimer = setInterval(()=>{ c--; if(c>=0) phase.textContent = c+ 's'; if(c<=0){ step=(step+1)%3; clearInterval(breathTimer); tick(); } },1000);
        }
        tick();
        stop.addEventListener('click',()=>{ clearInterval(breathTimer); breathTimer=null; modalBody.innerHTML='<div class="small">Practice stopped.</div>'; });
      }

      function startJournaling(){
        modalBody.innerHTML = '<div><p class="small">Free-write for 5 minutes. Use the prompt and then type below. Click Save when done.</p><p style="font-weight:700">Prompt: What would a softer day look like, and what’s one small step toward it?</p><textarea id="journal" rows="6" style="width:100%;margin-top:8px;border-radius:8px;padding:10px;border:1px solid #e9ddd2"></textarea><div style="display:flex;justify-content:space-between;margin-top:8px"><div class="small" id="timer">05:00</div><div><button class="kv" id="save-journal">Save</button> <button class="kv" id="cancel-journal">Close</button></div></div></div>';
        const timerEl = document.getElementById('timer');
        const save = document.getElementById('save-journal');
        const cancel = document.getElementById('cancel-journal');
        let remaining = 300; // seconds
        const interval = setInterval(()=>{
          remaining--; const mm = String(Math.floor(remaining/60)).padStart(2,'0'); const ss = String(remaining%60).padStart(2,'0'); timerEl.textContent = mm+':'+ss;
          if(remaining<=0){ clearInterval(interval); timerEl.textContent='00:00'; }
        },1000);
        save.addEventListener('click',()=>{ clearInterval(interval); const text=document.getElementById('journal').value; modalBody.innerHTML='<div class="small">Saved locally in this browser session. Your note:<pre style="white-space:pre-wrap;background:#f7f3f0;padding:10px;border-radius:8px">'+escapeHtml(text)+'</pre></div>'; });
        cancel.addEventListener('click',()=>{ clearInterval(interval); closeModal(); });
      }
      function startIntention(){
        modalBody.innerHTML = '<div style="text-align:center"><p class="small">Choose a single intention to carry through today. Make it specific and small.</p><input id="intent" placeholder="My intention..." style="width:100%;padding:10px;border-radius:8px;border:1px solid #e9ddd2" /><div style="margin-top:10px"><button class="kv" id="set-intent">Set intention</button> <button class="kv" id="close-intent">Close</button></div><div id="confirm" class="small" style="margin-top:10px;color:var(--muted)"></div></div>';
        document.getElementById('set-intent').addEventListener('click',()=>{ const t=document.getElementById('intent').value.trim(); if(!t){ document.getElementById('confirm').textContent='Please write a short intention.'; return;} document.getElementById('confirm').textContent='Intent set: "'+t+'" — keep it visible today.'; });
        document.getElementById('close-intent').addEventListener('click',closeModal);
      }

      function escapeHtml(str){ return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="An integrative perspective: who we are and how we partner with you for sustainable change.">
  <style>
    :root{--bg:#fffaf6;--accent:#8a4f2a;--muted:#6f5e56;--card:#fff1e9;--ink:#2b2a28;--shadow:0 10px 30px rgba(37,27,20,0.06);--pattern:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><rect width="160" height="160" fill="%23fffaf6"/><g stroke="%238a4f2a" stroke-opacity="0.05" stroke-width="1"><path d="M0 40 C20 0 40 80 60 40 S100 0 120 40" fill="none"/></g></svg>');}
    *{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg) var(--pattern);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#c0723a);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-weight:700}
    main{max-width:980px;margin:20px auto;padding:20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px}
    .muted{color:var(--muted)}
    .values{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
    .value{flex:1 1 140px;background:white;padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
    footer{margin-top:18px;color:var(--muted);font-size:13px}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    @media (max-width:880px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div class="muted" style="font-size:13px">A regional practice in {{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Begin</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Concerns</a>
      <a href="pricing.html">Invest</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <section class="card reveal" id="who">
        <h1>Who we are</h1>
        <p class="muted">A small team of clinicians and educators blending nutrition, lifestyle strategy, and evidence-informed tools. We listen first, map context second, and design focused steps that fit into your life.</p>

        <h3 style="margin-top:14px">Our approach</h3>
        <p class="muted">We prioritize understanding your environment—work, family, sleep patterns—then introduce a compact set of practices. Our work favors clarity over complexity: fewer changes, better tracked.</p>

        <div class="values">
          <div class="value">
            <strong>Context matters</strong>
            <div class="muted">We ask where your challenges show up rather than only naming what shows up.</div>
          </div>
          <div class="value">
            <strong>Education-first</strong>
            <div class="muted">You learn why a change matters and how to keep it simple.</div>
          </div>
          <div class="value">
            <strong>Measured steps</strong>
            <div class="muted">We set short experiments, measure signals, and adapt promptly.</div>
          </div>
        </div>
      </section>

      <aside class="card reveal" id="team">
        <h3>Lead clinicians</h3>
        <div style="margin-top:8px">
          <div style="font-weight:700">Dr. A. Rivera</div>
          <div class="muted">Integrative physician, long-term systems thinker</div>
        </div>
        <div style="margin-top:10px">
          <div style="font-weight:700">N. Patel, ND</div>
          <div class="muted">Lifestyle and nutrition advisor</div>
        </div>

        <hr style="margin:14px 0;border:none;border-top:1px solid rgba(0,0,0,0.04)" />
        <div class="muted">Contact our team: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      </aside>
    </div>

    <section class="card reveal" id="story" style="margin-top:18px">
      <h3>Our story</h3>
      <p class="muted">This practice started from the belief that deep work does not always require years; sometimes it requires a deliberate, intensive season. We partner with people who want structural shifts—sleep rhythms, daily energy, or stress responses—and give them the skillset and follow-through to make those shifts stick.</p>
    </section>

    <section class="card reveal" id="faq" style="margin-top:18px">
      <h3>Frequently asked</h3>
      <details>
        <summary>Do you accept insurance?</summary>
        <p class="muted">We operate primarily as a direct-pay practice but provide superbills and guidance for potential reimbursement. Contact us for specifics.</p>
      </details>

      <details style="margin-top:8px">
        <summary>Is this for acute conditions?</summary>
        <p class="muted">We provide education and structural plans. This is not a promise of cure; if you’ve got urgent medical needs, we coordinate with your existing care team.</p>
      </details>
    </section>

    <footer class="muted" style="margin-top:18px">Want to meet? <a href="book.html">Schedule a focused consult</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</footer>
  </main>

  <script>
    // Reveal handler duplicate protection but same behavior: respect prefers-reduced-motion
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduce){ items.forEach(i=>i.classList.add('visible')); return; }
      const io = new IntersectionObserver((list)=>{ list.forEach(entry=>{ if(entry.isIntersecting){ entry.target.classList.add('visible'); io.unobserve(entry.target); } }); },{threshold:0.12});
      items.forEach(i=>io.observe(i));
    })();
  </script>
</body>
</html>"} 
