<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a consult — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Schedule an initial focused consult. Choose a short intake or a deeper intake session.">
  <style>
    :root{--bg:#fff8f3;--accent:#8b4f26;--muted:#6b5b52;--card:#fff;--ink:#221f1e;--shadow:0 12px 36px rgba(33,23,18,0.06);}
    *{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#bb6e3a);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-weight:700}
    main{max-width:920px;margin:20px auto;padding:18px}
    .split{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    label{display:block;font-weight:700;margin-top:12px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #efe4da;margin-top:6px}
    .muted{color:var(--muted)}
    .btn-primary{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;font-weight:800}
    .mini{font-size:13px;color:var(--muted)}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    @media (max-width:880px){.split{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div class="muted" style="font-size:13px">Book a focused consult</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Begin</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Invest</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <div class="split">
      <section class="card reveal" id="form">
        <h2 style="margin-top:0">Schedule your consult</h2>
        <p class="muted">Choose a length and tell us a little about what you'd like to address. We’ll follow up with available times and the intake form.</p>

        <form id="booking-form" novalidate>
          <label for="name">Your full name</label>
          <input id="name" name="name" required />

          <label for="email">Email</label>
          <input id="email" name="email" type="email" required />

          <label for="phone">Phone</label>
          <input id="phone" name="phone" type="tel" />

          <label for="plan">Intake option</label>
          <select id="plan" name="plan">
            <option value="short">Short intake — 30 min (intro)</option>
            <option value="deep">Deep intake — 75 min (recommended for complex needs)</option>
            <option value="follow">Follow-up — 40 min</option>
          </select>

          <label for="notes">Brief note (what you hope to address)</label>
