  </main>

  <script>
    // reveal
    (function(){ const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; const nodes = document.querySelectorAll('.reveal'); if(prefersReduce){ nodes.forEach(n=>n.classList.add('visible')); return; } const io = new IntersectionObserver(entries=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); } }); },{threshold:0.12}); nodes.forEach(n=>io.observe(n)); })();

    // booking form local handler
    (function(){
      const form = document.getElementById('booking-form');
      const clear = document.getElementById('clear');
      form.addEventListener('submit', (ev)=>{
        ev.preventDefault();
        const name = form.name.value.trim(); const email = form.email.value.trim();
        if(!name || !email){ alert('Please provide name and email.'); return; }
        // emulate sending
        form.querySelector('.btn-primary').disabled = true; form.querySelector('.btn-primary').textContent = 'Sending...';
        setTimeout(()=>{
          form.innerHTML = '<div style="padding:18px;border-radius:10px;background:#fff9f6"><strong>Request sent</strong><div class="muted" style="margin-top:8px">We will follow up at '+escapeHtml(email)+' with available times. If urgent, call '+escapeHtml('{{PHONE}}')+'.</div></div>';
        },900);
      });
      clear.addEventListener('click',()=>{ form.reset(); });
      function escapeHtml(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
    })();
  </script>
